"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase"; // O Guarda
import Link from "next/link";
import Image from "next/image";
import { LayoutDashboard, FileText, Users, Settings, LogOut, Loader2 } from "lucide-react";

export default function AdminLayout({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const [loading, setLoading] = useState(true);

  // 🛡️ O GUARDA DE SEGURANÇA
  useEffect(() => {
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        router.push("/login"); // Se não tiver crachá, vai pro login
      } else {
        setLoading(false); // Pode entrar
      }
    };
    checkUser();
  }, [router]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/login");
  };

  if (loading) {
    return (
      <div className="flex h-screen w-full items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <Loader2 className="h-10 w-10 animate-spin text-blue-600" />
          <p className="text-slate-500 font-medium">Verificando credenciais...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-100">
      {/* Barra Lateral (Sidebar) */}
      <aside className="w-64 bg-slate-900 text-white hidden md:flex flex-col border-r border-slate-800 shadow-xl z-20">
        <div className="p-6 border-b border-slate-800 flex items-center gap-3">
          {/* LOGO OFICIAL AQUI */}
          <div className="relative h-10 w-10 shrink-0">
             <Image 
               src="/logo-nexus.png"
               alt="Logo"
               fill
               className="object-contain"
             />
          </div>
          <div>
            <h2 className="text-xl font-bold tracking-tight text-white leading-none">
              NEXUS<span className="text-blue-500">CORP</span>
            </h2>
            <p className="text-[10px] text-slate-400 mt-1 uppercase tracking-wider font-bold">Gestão Inteligente</p>
          </div>
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2">
          <Link href="/admin" className="flex items-center gap-3 px-4 py-3 text-slate-300 hover:bg-slate-800 hover:text-white rounded-xl transition-all font-medium">
            <LayoutDashboard size={20} />
            Visão Geral
          </Link>
          <Link href="/admin/protocolos" className="flex items-center gap-3 px-4 py-3 text-slate-300 hover:bg-slate-800 hover:text-white rounded-xl transition-all font-medium">
            <FileText size={20} />
            Protocolos
          </Link>
          <Link href="/admin/cidadaos" className="flex items-center gap-3 px-4 py-3 text-slate-300 hover:bg-slate-800 hover:text-white rounded-xl transition-all font-medium">
            <Users size={20} />
            Cidadãos
          </Link>
          <Link href="/admin/config" className="flex items-center gap-3 px-4 py-3 text-slate-300 hover:bg-slate-800 hover:text-white rounded-xl transition-all font-medium">
            <Settings size={20} />
            Configurações
          </Link>
        </nav>

        <div className="p-4 border-t border-slate-800">
          <button onClick={handleLogout} className="flex w-full items-center gap-3 px-4 py-3 text-red-400 hover:bg-red-500/10 hover:text-red-300 rounded-xl transition-colors font-bold text-sm">
            <LogOut size={18} />
            Sair do Sistema
          </button>
        </div>
      </aside>

      {/* Conteúdo Principal */}
      <main className="flex-1 p-8 overflow-y-auto">
        {children}
      </main>
    </div>
  );
}